# filename: verify_supersession_validator.py
import requests
from bs4 import BeautifulSoup
import re

categories = {
    "dried fruit": ["dried apples", "dried apricots", "dried peaches", "dried pears", "dried figs", "prunes", "raisins"],
    "dehydrated vegetables": ["dehydrated onions", "dehydrated garlic", "dehydrated carrots", "dehydrated celery", "dehydrated potatoes", "dehydrated spinach", "dehydrated sweetpotatoes"],
    "frozen fruits and vegetables": ["frozen apples", "frozen apricots", "frozen peaches", "frozen pears", "frozen prunes", "frozen onions", "frozen potatoes", "frozen carrots", "frozen spinach"]
}

category_queries = {
    "dried fruit": "United States Standards for Grades dried fruit",
    "dehydrated vegetables": "United States Standards for Grades dehydrated vegetables",
    "frozen fruits and vegetables": "United States Standards for Grades frozen fruits vegetables"
}

base = "https://www.ams.usda.gov/search?search_api_fulltext={q}&f[0]=field_document_type%3Astandards"

def latest_year_for_query(q):
    r = requests.get(base.format(q=q.replace(" ", "+")), timeout=10)
    if r.status_code != 200:
        return None
    soup = BeautifulSoup(r.text, "html.parser")
    years = [int(y) for y in re.findall(r"19\d{2}|20\d{2}", soup.get_text().lower())]
    return max(years) if years else None

if __name__ == "__main__":
    cat_latest = {}
    for cat, q in category_queries.items():
        cat_latest[cat] = latest_year_for_query(q)
    print("Category latest years:", cat_latest)
    all_items = []
    for cat, items in categories.items():
        for it in items:
            # Superseded if latest category year > 1959
            superseded = (cat_latest[cat] is not None and cat_latest[cat] > 1959)
            all_items.append((it, superseded, cat_latest[cat]))
    print("Supersession flags:")
    for it, sup, yr in all_items:
        print(f"- {it}: {sup} (category latest: {yr})")
    pct = round(sum(1 for _, sup, _ in all_items if sup) / len(all_items) * 100)
    print(f"Computed percentage superseded: {pct}%")
